from __future__ import annotations

import os
import shutil
import subprocess
import sys
import webbrowser
from pathlib import Path

import typer

NAME = "delulu-smash"
REPO_DIR = Path(__file__).resolve().parents[3]
URL = "http://localhost:3000"
WINDOWS = sys.platform == "win32"
# Windows: a console program started from pythonw would open a console window
NO_WINDOW = 0x08000000 if WINDOWS else 0
# Windows toast through PowerShell's own app id (a toast needs a registered one); text via env
TOAST_PS = """
$m = [Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime]
$xml = $m::GetTemplateContent([Windows.UI.Notifications.ToastTemplateType]::ToastText02)
$text = $xml.GetElementsByTagName('text')
$text.Item(0).AppendChild($xml.CreateTextNode($env:DS_TOAST_TITLE)) | Out-Null
$text.Item(1).AppendChild($xml.CreateTextNode($env:DS_TOAST_BODY)) | Out-Null
$app = '{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\\WindowsPowerShell\\v1.0\\powershell.exe'
$m::CreateToastNotifier($app).Show([Windows.UI.Notifications.ToastNotification]::new($xml))
"""

app = typer.Typer(add_completion=False, no_args_is_help=False, help=__doc__)


def ds_ui(command: str) -> bool:
    """Run `ds ui <command>` (no `ds` alias here); True when it exits 0."""
    args = ["uv", "run", "--project", str(REPO_DIR), "ds", "ui", command]
    return subprocess.run(args, check=False, creationflags=NO_WINDOW).returncode == 0


def notify(message: str, *, critical: bool = False) -> None:
    """A desktop notification (a keybinding has no terminal to print to)."""
    if WINDOWS:
        env = {**os.environ, "DS_TOAST_TITLE": NAME, "DS_TOAST_BODY": message}
        script = ["powershell", "-NoProfile", "-NonInteractive", "-Command", TOAST_PS]
        subprocess.Popen(script, env=env, creationflags=NO_WINDOW)  # not waited for: the toast is best effort
    elif shutil.which("notify-send"):
        urgency = ["-u", "critical"] if critical else []
        subprocess.run(["notify-send", *urgency, "-a", NAME, NAME, message], check=False)


def focus_windows_window(title: str) -> bool:
    """Bring the window titled exactly `title` to the front; False when there is none.

    An Edge app window's title is the page's ("delulu-smash"); a normal browser window adds
    " - Microsoft Edge" (or its browser's name), so a plain tab on the same page doesn't match.
    """
    import ctypes  # here, not at the top: windll exists on Windows only
    from ctypes import wintypes

    user32 = ctypes.windll.user32
    found: list[int] = []

    @ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
    def visit(hwnd: int, _: int) -> bool:
        length = user32.GetWindowTextLengthW(hwnd)
        if length and user32.IsWindowVisible(hwnd):
            buffer = ctypes.create_unicode_buffer(length + 1)
            user32.GetWindowTextW(hwnd, buffer, length + 1)
            if buffer.value == title:
                found.append(hwnd)
                return False  # stop: found
        return True

    user32.EnumWindows(visit, 0)
    if not found:
        return False
    if user32.IsIconic(found[0]):
        user32.ShowWindow(found[0], 9)  # SW_RESTORE: un-minimize
    user32.SetForegroundWindow(found[0])
    return True


def edge() -> str | None:
    """msedge.exe: rarely on PATH, so also its install folders."""
    if found := shutil.which("msedge"):
        return found
    for var in ("ProgramFiles(x86)", "ProgramFiles", "LOCALAPPDATA"):
        base = os.environ.get(var)
        path = Path(base) / "Microsoft" / "Edge" / "Application" / "msedge.exe" if base else None
        if path and path.exists():
            return str(path)
    return None


def open_windows_window() -> None:
    """Windows: focus the open app window, else open one (Edge app mode, else a tab)."""
    if focus_windows_window(NAME):
        return
    if browser := edge():
        subprocess.Popen([browser, f"--app={URL}"])
    else:
        webbrowser.open(URL)


@app.command()
def open_window() -> None:
    """Start the server if it's down, then open the window or focus the open one"""
    if not ds_ui("status"):
        notify("Starting delulu-smash, this takes up to a minute…")
        # restarting a stopped service starts it, and `restart` waits until the app answers
        if not ds_ui("restart"):
            logs = "ds ui logs" if WINDOWS else "journalctl --user -u delulu-smash"
            notify(f"Server didn't come up. Check: {logs}", critical=True)
            raise typer.Exit(1)
    if WINDOWS:
        open_windows_window()
        return
    # Match the web app window by its class (Chromium derives it from the URL), not the
    # title: a normal browser tab on the same page is also titled "delulu-smash".
    window_class = subprocess.run(
        ["omarchy-webapp-window-class", URL], capture_output=True, text=True, check=True
    ).stdout.strip()
    launcher = ["omarchy-launch-or-focus-webapp", window_class, URL]
    os.execvp(launcher[0], launcher)  # noqa: S606  # fixed command, replaces this process


if __name__ == "__main__":
    app()
